package com.parkflow.security;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.*;import org.springframework.security.config.http.SessionCreationPolicy;
@Configuration public class SecurityConfig{@Bean SecurityFilterChain filterChain(HttpSecurity http,TokenFilter filter)throws Exception{return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.anyRequest().permitAll()).addFilterBefore(filter,org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter.class).build();}}
